// Validate RAG Researcher structured output
const input = $input.first().json;
let output = input.output || input.response || input.text || input.content || '';

let parsed;
try {
  const mdMatch = output.match(/```json\n([\s\S]*?)\n```/) || output.match(/```\n([\s\S]*?)\n```/);
  if (mdMatch && mdMatch[1]) {
    parsed = JSON.parse(mdMatch[1].trim());
  } else {
    const jsonMatch = output.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    else parsed = JSON.parse(output);
  }
} catch (e) {
  return [{
    json: {
      valid: false,
      error: 'Parse error: ' + e.message,
      raw_output: output.substring(0, 3000),
      research_brief: { topic: '', key_apis: [], architecture_patterns: [], business_rules: [], data_models: [], security_considerations: [], performance_requirements: [], integration_points: [] },
      gaps: ['Failed to parse research output'],
      confidence: 'low',
      sources_consulted: []
    }
  }];
}

if (!parsed.research_brief) parsed.research_brief = { topic: '', key_apis: [], architecture_patterns: [], business_rules: [], data_models: [], security_considerations: [], performance_requirements: [], integration_points: [] };
if (!parsed.gaps) parsed.gaps = [];
if (!parsed.confidence) parsed.confidence = 'low';
if (!parsed.sources_consulted) parsed.sources_consulted = [];

// Validate arrays
const arrFields = ['key_apis', 'architecture_patterns', 'business_rules', 'data_models', 'security_considerations', 'performance_requirements', 'integration_points'];
for (const f of arrFields) {
  if (!Array.isArray(parsed.research_brief[f])) parsed.research_brief[f] = [];
}

return [{ json: { valid: true, ...parsed } }];
